// Per-icon sprite cache. Each 96×96 fusion sprite is cropped out of its
// sheet once and stored as a standalone PNG Blob in IndexedDB.
//
// Two key schemes coexist:
//   - "${a}-${b}"           : autogenerated sprite (fallback)
//   - "${a}-${b}:c${i}"     : hand-drawn custom variant index `i`
//                              (i is into the per-cell variant list)
//
// Per-cell variant counts live in the `variants` store keyed "${a}-${b}".
// Cells absent from that store have no custom variants → autogen fallback.
//
//   Sprites.getSpriteUrl(a, b, variant) -> Promise<objectURL string>
//     variant: integer (custom index), or null/'auto' (autogen).
//   Sprites.getCellVariantCount(a, b)   -> Promise<integer>
//
// Caller is responsible for URL.revokeObjectURL once the image has loaded.

(function (global) {
  'use strict';

  const DB_NAME = 'creature-sprites-v1';
  const DB_VERSION = 2;
  const STORE_ICONS = 'icons';
  const STORE_VARIANTS = 'variants';
  const SPRITE_SIZE = 96;
  // Autogen sheets are 960×4896 → 10 cols × 51 rows. Custom (hand-
  // drawn) sheets pack denser — typically 1920×2784 → 20 cols × 29
  // rows. Both use 96×96 cells, but the column count differs, so
  // crops compute `cols = bitmap.width / SPRITE_SIZE` per-sheet rather
  // than relying on a single constant.
  const SHEET_COLS_AUTOGEN = 10;
  const ALPHA_MIN = 8;
  // Sheets are huge ImageBitmaps (~18 MB decoded each). We only need
  // a tiny cache because bulk download processes them sequentially and
  // explicitly releases after cropping; after that the cache is empty.
  const MAX_SHEET_CACHE = 2;
  // A custom-sheet cell is "filled" if any pixel in its 96×96 region
  // is above ALPHA_MIN. Bulk download alpha-scans every cell of every
  // variant sheet and writes a non-blank-variants array per cell.
  const SPECIES_MAX = 150;

  let _dbPromise = null;
  let _customManifest = null;     // species id (string) -> [variant suffixes]
  let _customManifestPromise = null;
  // In-memory cache of the per-cell variant index map: `${a}-${b}` ->
  // number of custom variants. Filled on first call after IDB is open.
  let _variantCountCache = null;
  let _variantCountPromise = null;
  // Diagnostic counter — number of sprite reads currently in flight.
  // Wraps every IDB blob fetch (single + batch). Surfaced via
  // Sprites.getInflightCount() for the Settings debug badge so we
  // can confirm lazy-loading is actually happening (count should
  // stay in single digits if only visible spawns are being fetched).
  let _inflightSpriteReads = 0;
  function _incInflight() { _inflightSpriteReads++; }
  function _decInflight() { if (_inflightSpriteReads > 0) _inflightSpriteReads--; }

  // Diagnostic error log surfaced via the Settings badge. Capped so a
  // looping failure can't blow up memory; a global counter still
  // increments past the cap.
  function _logSpriteError(where, err) {
    if (typeof window === 'undefined') return;
    window._spriteDiag = window._spriteDiag || {};
    window._spriteDiag.errorCount = (window._spriteDiag.errorCount || 0) + 1;
    window._spriteDiag.errors = window._spriteDiag.errors || [];
    if (window._spriteDiag.errors.length < 10) {
      const msg = (err && err.message) ? err.message : String(err);
      window._spriteDiag.errors.push(`${where}: ${msg}`);
    }
  }

  function openDb() {
    if (_dbPromise) return _dbPromise;
    _dbPromise = new Promise((resolve, reject) => {
      const req = indexedDB.open(DB_NAME, DB_VERSION);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(STORE_ICONS)) {
          db.createObjectStore(STORE_ICONS);
        }
        if (!db.objectStoreNames.contains(STORE_VARIANTS)) {
          db.createObjectStore(STORE_VARIANTS);
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
    return _dbPromise;
  }

  function _idbReq(store, mode, fn) {
    return openDb().then((db) => new Promise((resolve, reject) => {
      const tx = db.transaction(store, mode);
      const req = fn(tx.objectStore(store));
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    }));
  }
  const idbGet  = (key)        => _idbReq(STORE_ICONS,    'readonly',  (s) => s.get(key));
  const idbPut  = (key, value) => _idbReq(STORE_ICONS,    'readwrite', (s) => s.put(value, key));
  const varGet  = (key)        => _idbReq(STORE_VARIANTS, 'readonly',  (s) => s.get(key));
  const varPut  = (key, value) => _idbReq(STORE_VARIANTS, 'readwrite', (s) => s.put(value, key));

  // LRU of decoded sheets. Keyed by URL; values are ImageBitmaps.
  const _sheetCache = new Map();
  const _sheetPromises = new Map();

  async function fetchAndDecode(url) {
    if (_sheetCache.has(url)) {
      const bmp = _sheetCache.get(url);
      _sheetCache.delete(url);
      _sheetCache.set(url, bmp);
      return bmp;
    }
    if (_sheetPromises.has(url)) return _sheetPromises.get(url);

    const p = (async () => {
      const resp = await fetch(url);
      if (!resp.ok) throw new Error(`${url}: HTTP ${resp.status}`);
      const blob = await resp.blob();
      const bmp = await createImageBitmap(blob);
      _sheetCache.set(url, bmp);
      while (_sheetCache.size > MAX_SHEET_CACHE) {
        const firstKey = _sheetCache.keys().next().value;
        const old = _sheetCache.get(firstKey);
        _sheetCache.delete(firstKey);
        if (old && old.close) old.close();
      }
      return bmp;
    })();
    _sheetPromises.set(url, p);
    try { return await p; }
    finally { _sheetPromises.delete(url); }
  }

  function getSheetBitmap(sheetIdx) {
    return fetchAndDecode(`/creature-sprite/${sheetIdx}`);
  }
  function getCustomSheetBitmap(species, variant) {
    const url = variant
      ? `/creature-sprite-custom/${species}/${variant}`
      : `/creature-sprite-custom/${species}`;
    return fetchAndDecode(url);
  }

  function makeCanvas(w, h) {
    if (typeof OffscreenCanvas !== 'undefined') return new OffscreenCanvas(w, h);
    const c = document.createElement('canvas');
    c.width = w; c.height = h;
    return c;
  }

  function canvasToBlob(canvas) {
    if (canvas.convertToBlob) return canvas.convertToBlob({ type: 'image/png' });
    return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
  }

  // Scan pixel alpha, return { bbox, blob }. bbox is null when the
  // cell is fully transparent (all alpha < ALPHA_MIN). We return both
  // because bulk download wants the bbox for blank-detection without
  // re-scanning, while the cropped Blob is ready to write to IDB.
  async function scanAndCrop(srcBitmap, sx, sy, sw, sh) {
    const scan = makeCanvas(sw, sh);
    const sctx = scan.getContext('2d');
    sctx.drawImage(srcBitmap, sx, sy, sw, sh, 0, 0, sw, sh);
    const data = sctx.getImageData(0, 0, sw, sh).data;
    let minX = sw, minY = sh, maxX = -1, maxY = -1;
    for (let y = 0; y < sh; y++) {
      const rowOff = y * sw * 4 + 3;
      for (let x = 0; x < sw; x++) {
        if (data[rowOff + x * 4] > ALPHA_MIN) {
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
        }
      }
    }
    if (maxX < 0) return { bbox: null, blob: null };
    const cw = maxX - minX + 1;
    const ch = maxY - minY + 1;
    const out = makeCanvas(cw, ch);
    out.getContext('2d').drawImage(scan, minX, minY, cw, ch, 0, 0, cw, ch);
    const blob = await canvasToBlob(out);
    return { bbox: { minX, minY, maxX, maxY }, blob };
  }

  // Crop a sprite from an autogen sheet. Falls back to the untrimmed
  // 96×96 if the cell is fully transparent (which shouldn't happen for
  // autogen but matches the legacy behaviour).
  async function cropAutogenSprite(bitmap, index) {
    const col = index % SHEET_COLS_AUTOGEN;
    const row = Math.floor(index / SHEET_COLS_AUTOGEN);
    const { blob } = await scanAndCrop(
      bitmap, col * SPRITE_SIZE, row * SPRITE_SIZE, SPRITE_SIZE, SPRITE_SIZE
    );
    if (blob) return blob;
    const fallback = makeCanvas(SPRITE_SIZE, SPRITE_SIZE);
    fallback.getContext('2d').drawImage(
      bitmap,
      col * SPRITE_SIZE, row * SPRITE_SIZE, SPRITE_SIZE, SPRITE_SIZE,
      0, 0, SPRITE_SIZE, SPRITE_SIZE
    );
    return canvasToBlob(fallback);
  }

  // Crop one cell of a custom sheet. Returns null when the cell is
  // blank — caller skips writing it to IDB. Distinct from the autogen
  // version: blank cells in a custom sheet are EXPECTED (artists only
  // fill in some fusions), and we MUST drop them so the per-cell
  // variant list reflects which variants are actually drawn.
  // Custom sheets use a different column count from autogen (typically
  // 20 cols × 29 rows for a 1920×2784 sheet vs autogen's 10 × 51), so
  // we derive cols from the bitmap width.
  async function cropCustomSpriteIfFilled(bitmap, index) {
    const cols = Math.max(1, Math.floor(bitmap.width / SPRITE_SIZE));
    const col = index % cols;
    const row = Math.floor(index / cols);
    if ((row + 1) * SPRITE_SIZE > bitmap.height) return null;
    const { blob } = await scanAndCrop(
      bitmap, col * SPRITE_SIZE, row * SPRITE_SIZE, SPRITE_SIZE, SPRITE_SIZE
    );
    return blob;  // null if blank
  }

  function customKey(a, b, variantIdx) {
    return `${a}-${b}:c${variantIdx}`;
  }
  function autogenKey(a, b) {
    return `${a}-${b}`;
  }

  // Variant counts are read from a SINGLE compact summary blob in
  // IDB — `Uint8Array(150 * 150) = 22 500 bytes` indexed by
  // `(a-1) * 150 + (b-1)`. One IDB get = a few milliseconds even on
  // iOS PWA, vs. the previous 67-second walk of ~17 600 entries.
  // The summary is written at the end of bulkDownload pass 2; if
  // a user hasn't downloaded under this scheme yet, we fall back to
  // a per-cell lookup (slow first miss, cached after) so existing
  // sprites still render.
  const VARIANT_SUMMARY_KEY = '__summary__';
  const SPECIES_MAX_DIM = 150;
  let _variantSummaryLoaded = false;
  const _variantInflight = new Map();  // key -> Promise<number>

  function _summaryIndex(a, b) {
    if (a < 1 || a > SPECIES_MAX_DIM || b < 1 || b > SPECIES_MAX_DIM) return -1;
    return (a - 1) * SPECIES_MAX_DIM + (b - 1);
  }

  // Read the compact summary blob ONCE per session. After it lands,
  // every getCellVariantCount becomes an O(1) Map lookup.
  // Concurrent callers share one in-flight read.
  let _variantSummaryPromise = null;
  function _ensureVariantSummary() {
    if (_variantSummaryLoaded) return Promise.resolve();
    if (_variantSummaryPromise) return _variantSummaryPromise;
    _variantSummaryPromise = (async () => {
      const t0 = (typeof performance !== 'undefined') ? performance.now() : 0;
      let db;
      try { db = await openDb(); }
      catch (e) { _logSpriteError('ensureVariantSummary/openDb', e); _variantSummaryLoaded = true; return; }
      const blob = await new Promise((resolve) => {
        try {
          const tx = db.transaction(STORE_VARIANTS, 'readonly');
          const r = tx.objectStore(STORE_VARIANTS).get(VARIANT_SUMMARY_KEY);
          r.onsuccess = () => resolve(r.result || null);
          r.onerror = () => { _logSpriteError('ensureVariantSummary/get', r.error); resolve(null); };
        } catch (e) { _logSpriteError('ensureVariantSummary/setup', e); resolve(null); }
      });
      const cache = _variantCountCache || (_variantCountCache = new Map());
      if (blob && blob.byteLength === SPECIES_MAX_DIM * SPECIES_MAX_DIM) {
        const arr = new Uint8Array(blob);
        for (let a = 1; a <= SPECIES_MAX_DIM; a++) {
          for (let b = 1; b <= SPECIES_MAX_DIM; b++) {
            const c = arr[(a - 1) * SPECIES_MAX_DIM + (b - 1)];
            if (c > 0) cache.set(`${a}-${b}`, c);
          }
        }
      }
      _variantSummaryLoaded = true;
      if (typeof window !== 'undefined') {
        window._spriteDiag = window._spriteDiag || {};
        window._spriteDiag.variantSummaryMs = (typeof performance !== 'undefined')
          ? performance.now() - t0 : 0;
        window._spriteDiag.variantSummaryHadBlob = !!blob;
        window._spriteDiag.variantsCount = cache.size;
      }
    })();
    _variantSummaryPromise.finally(() => { _variantSummaryPromise = null; });
    return _variantSummaryPromise;
  }

  // Build + persist the summary blob. Called at end of bulkDownload
  // pass 2 — walks the per-cell entries currently in IDB, packs
  // counts into a Uint8Array, writes it under VARIANT_SUMMARY_KEY.
  // Idempotent: safe to call again to refresh.
  async function _writeVariantSummary() {
    let db;
    try { db = await openDb(); }
    catch (e) { _logSpriteError('writeVariantSummary/openDb', e); return; }
    // Read existing per-cell entries via cursor (one-time cost,
    // user already paid for the download).
    const arr = new Uint8Array(SPECIES_MAX_DIM * SPECIES_MAX_DIM);
    await new Promise((resolve) => {
      try {
        const tx = db.transaction(STORE_VARIANTS, 'readonly');
        const cur = tx.objectStore(STORE_VARIANTS).openCursor();
        cur.onsuccess = () => {
          const c = cur.result;
          if (!c) { resolve(); return; }
          const key = c.key;
          if (typeof key === 'string' && key !== VARIANT_SUMMARY_KEY) {
            const dash = key.indexOf('-');
            if (dash > 0) {
              const a = +key.slice(0, dash);
              const b = +key.slice(dash + 1);
              const idx = _summaryIndex(a, b);
              const v = c.value;
              if (idx >= 0 && Array.isArray(v) && v.length > 0) {
                arr[idx] = Math.min(255, v.length);
              }
            }
          }
          c.continue();
        };
        cur.onerror = () => { _logSpriteError('writeVariantSummary/cursor', cur.error); resolve(); };
      } catch (e) { _logSpriteError('writeVariantSummary/setup', e); resolve(); }
    });
    await new Promise((resolve) => {
      try {
        const tx = db.transaction(STORE_VARIANTS, 'readwrite');
        tx.objectStore(STORE_VARIANTS).put(arr.buffer, VARIANT_SUMMARY_KEY);
        tx.oncomplete = () => resolve();
        tx.onerror = () => { _logSpriteError('writeVariantSummary/put', tx.error); resolve(); };
      } catch (e) { _logSpriteError('writeVariantSummary/putSetup', e); resolve(); }
    });
    _variantSummaryLoaded = true;  // we just wrote it; cache is authoritative
  }

  async function _readVariantCount(key) {
    let db;
    try { db = await openDb(); }
    catch (e) { _logSpriteError('readVariantCount/openDb', e); return 0; }
    return new Promise((resolve) => {
      try {
        const tx = db.transaction(STORE_VARIANTS, 'readonly');
        const r = tx.objectStore(STORE_VARIANTS).get(key);
        r.onsuccess = () => {
          const v = r.result;
          resolve((Array.isArray(v) && v.length > 0) ? v.length : 0);
        };
        r.onerror = () => { _logSpriteError(`readVariantCount/${key}`, r.error); resolve(0); };
      } catch (e) {
        _logSpriteError(`readVariantCount/tx/${key}`, e);
        resolve(0);
      }
    });
  }

  async function getCellVariantCount(a, b) {
    // Fast path — summary already loaded, just check the in-memory map.
    await _ensureVariantSummary();
    const key = `${a}-${b}`;
    const cache = _variantCountCache || (_variantCountCache = new Map());
    if (cache.has(key)) return cache.get(key);
    // Slow fallback: summary missing or this cell wasn't in it. Look
    // up the per-cell entry directly. Future visits hit cache.
    if (_variantInflight.has(key)) return _variantInflight.get(key);
    const p = _readVariantCount(key);
    _variantInflight.set(key, p);
    try {
      const count = await p;
      cache.set(key, count);
      return count;
    } finally {
      _variantInflight.delete(key);
    }
  }

  // Batch: fetch counts for many (a, b) cells. With the summary
  // loaded, every cell hits cache → no IDB transaction at all.
  // Without the summary, falls back to a single pipelined transaction
  // over the uncached cells.
  async function getCellVariantCountsBatch(cells) {
    await _ensureVariantSummary();
    const cache = _variantCountCache || (_variantCountCache = new Map());
    const result = new Map();
    const need = [];
    for (const [a, b] of cells) {
      const key = `${a}-${b}`;
      if (cache.has(key)) result.set(key, cache.get(key));
      else need.push(key);
    }
    if (!need.length) return result;
    const t0 = (typeof performance !== 'undefined') ? performance.now() : 0;
    let db;
    try { db = await openDb(); }
    catch (e) {
      _logSpriteError('getCellVariantCountsBatch/openDb', e);
      for (const k of need) { cache.set(k, 0); result.set(k, 0); }
      return result;
    }
    const counts = await new Promise((resolve) => {
      try {
        const tx = db.transaction(STORE_VARIANTS, 'readonly');
        const store = tx.objectStore(STORE_VARIANTS);
        const out = new Array(need.length);
        let pending = need.length;
        need.forEach((k, i) => {
          const r = store.get(k);
          r.onsuccess = () => {
            const v = r.result;
            out[i] = (Array.isArray(v) && v.length > 0) ? v.length : 0;
            if (--pending === 0) resolve(out);
          };
          r.onerror = () => { out[i] = 0; if (--pending === 0) resolve(out); };
        });
        tx.onerror = () => {
          _logSpriteError('getCellVariantCountsBatch/tx', tx.error);
          for (let i = 0; i < need.length; i++) if (out[i] === undefined) out[i] = 0;
          resolve(out);
        };
      } catch (e) {
        _logSpriteError('getCellVariantCountsBatch/setup', e);
        resolve(need.map(() => 0));
      }
    });
    for (let i = 0; i < need.length; i++) {
      cache.set(need[i], counts[i]);
      result.set(need[i], counts[i]);
    }
    if (typeof window !== 'undefined') {
      window._spriteDiag = window._spriteDiag || {};
      window._spriteDiag.lastVariantBatch = need.length;
      window._spriteDiag.lastVariantBatchMs = (typeof performance !== 'undefined')
        ? performance.now() - t0 : 0;
      window._spriteDiag.variantsCount = cache.size;
    }
    return result;
  }

  function _bumpVariantCacheEntry(key, count) {
    if (!_variantCountCache) return;
    if (count > 0) _variantCountCache.set(key, count);
    else _variantCountCache.delete(key);
  }

  async function getSpriteBlob(a, b, variant) {
    const isCustom = (typeof variant === 'number' && variant >= 0);
    const key = isCustom ? customKey(a, b, variant) : autogenKey(a, b);
    _incInflight();
    let cached;
    try { cached = await idbGet(key); }
    catch (e) { _logSpriteError(`getSpriteBlob/${key}`, e); cached = null; }
    finally { _decInflight(); }
    if (cached) {
      // Self-heal: legacy autogen v1 crops were stored as full 96×96 PNGs
      // with transparent padding around the creature. Trim on first
      // access so markers self-correct without a full re-download.
      // Custom crops are written tight from the start, so this only
      // applies to the autogen key.
      if (!isCustom && await isLegacyPaddedPng(cached)) {
        const trimmed = await retrimStoredBlob(cached);
        if (trimmed) {
          idbPut(key, trimmed).catch(() => {});
          return trimmed;
        }
      }
      return cached;
    }
    return null;
  }

  async function getSpriteUrl(a, b, variant) {
    const blob = await getSpriteBlob(a, b, variant);
    if (!blob) return null;
    return URL.createObjectURL(blob);
  }

  // Bulk lookup: open ONE readonly transaction and fire all gets
  // inside it, instead of per-call transactions. Crucial on iOS
  // Safari, which serializes IDB transactions — ~50 individual
  // markers each opening their own transaction translates to seconds
  // of staggered sprite appearances. With one transaction the OS
  // pipelines all the reads.
  //
  // requests: Array<{ a, b, variant, key? }>  // key is the caller's
  //   stable id (e.g. spawn id) so they can correlate results.
  // Returns: Array<{ key, blob }> in the same order as `requests`,
  //   with blob === null for entries that aren't in IDB. Does NOT
  //   handle the legacy-padded-PNG self-heal path (rare, and the
  //   per-call getSpriteBlob is still the right place for that).
  async function getSpriteBlobsBatch(requests) {
    if (!requests || !requests.length) return [];
    let db;
    try { db = await openDb(); }
    catch (e) { _logSpriteError('getSpriteBlobsBatch/openDb', e); return requests.map((r, i) => ({ key: r.key != null ? r.key : i, blob: null })); }
    // Diagnostic — per-batch timing + size.
    const tBatch = (typeof performance !== 'undefined') ? performance.now() : 0;
    if (typeof window !== 'undefined') {
      window._spriteDiag = window._spriteDiag || {};
      window._spriteDiag.lastBatchSize = requests.length;
      window._spriteDiag.batchCount = (window._spriteDiag.batchCount || 0) + 1;
    }
    // Each entry in the batch counts as one in-flight read so the
    // debug badge reflects the true scope of work, not just one
    // "transaction".
    for (let i = 0; i < requests.length; i++) _incInflight();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_ICONS, 'readonly');
      const store = tx.objectStore(STORE_ICONS);
      const results = new Array(requests.length);
      let pending = requests.length;
      requests.forEach((req, i) => {
        const key = (typeof req.variant === 'number' && req.variant >= 0)
          ? customKey(req.a, req.b, req.variant)
          : autogenKey(req.a, req.b);
        const r = store.get(key);
        r.onsuccess = () => {
          results[i] = { key: req.key != null ? req.key : key, blob: r.result || null };
          _decInflight();
          if (--pending === 0) {
            if (typeof window !== 'undefined' && window._spriteDiag) {
              window._spriteDiag.lastBatchMs = (typeof performance !== 'undefined')
                ? performance.now() - tBatch : 0;
            }
            resolve(results);
          }
        };
        r.onerror = () => {
          results[i] = { key: req.key != null ? req.key : key, blob: null };
          _decInflight();
          if (--pending === 0) resolve(results);
        };
      });
      tx.onerror = () => {
        // If the whole transaction blows up, drain any remaining
        // counts so the badge can return to zero.
        for (let i = 0; i < pending; i++) _decInflight();
        _logSpriteError('getSpriteBlobsBatch/tx', tx.error);
        // Don't reject — return null blobs so callers can fall back
        // gracefully to per-marker getSpriteBlob (which has its own
        // error handling).
        for (let i = 0; i < requests.length; i++) {
          if (results[i] === undefined) {
            results[i] = { key: requests[i].key != null ? requests[i].key : i, blob: null };
          }
        }
        resolve(results);
      };
    });
  }

  function getInflightCount() { return _inflightSpriteReads; }

  // Abstract views (pokédex, evolution previews, family grids) don't
  // have a specific spawn or capture in hand, so they pick the "best
  // available" sprite for the cell: variant 0 (the artist's primary)
  // when the cell has any custom variants, autogen otherwise. Falls
  // back to autogen if variant 0 isn't on disk for any reason.
  async function getDefaultSpriteBlob(a, b) {
    const count = await getCellVariantCount(a, b);
    if (count > 0) {
      const blob = await getSpriteBlob(a, b, 0);
      if (blob) return blob;
    }
    return getSpriteBlob(a, b, null);
  }

  async function getDefaultSpriteUrl(a, b) {
    const blob = await getDefaultSpriteBlob(a, b);
    if (!blob) return null;
    return URL.createObjectURL(blob);
  }

  // Prefetch tracking — sheet is "done" only when every crop in
  // [indexFrom..indexTo] has been written to IDB.
  const DOWNLOADED_KEY = 'cc.spritesDownloaded';
  // Bumped from `cc.spritesCustomDone` after the cell-layout fix
  // (custom sheets are 20 cols × 29 rows, not 10 × 29). With the new
  // key, any user who downloaded under the broken layout will see
  // custom as "0/150 done" and can trigger a fresh download — pass 2
  // will overwrite their corrupt slots with correct ones.
  const CUSTOM_DONE_KEY = 'cc.spritesCustomDone.v2';

  function getDownloadedSheets() {
    try {
      const raw = localStorage.getItem(DOWNLOADED_KEY);
      return raw ? new Set(JSON.parse(raw)) : new Set();
    } catch { return new Set(); }
  }
  function getCustomDoneSpecies() {
    try {
      const raw = localStorage.getItem(CUSTOM_DONE_KEY);
      return raw ? new Set(JSON.parse(raw)) : new Set();
    } catch { return new Set(); }
  }
  function markCustomDone(species) {
    const set = getCustomDoneSpecies();
    set.add(species);
    localStorage.setItem(CUSTOM_DONE_KEY,
      JSON.stringify([...set].sort((a, b) => a - b)));
  }
  function markSheetDownloaded(sheetIdx) {
    const set = getDownloadedSheets();
    set.add(sheetIdx);
    localStorage.setItem(DOWNLOADED_KEY, JSON.stringify([...set].sort((a, b) => a - b)));
  }

  async function getCustomManifest() {
    if (_customManifest) return _customManifest;
    if (_customManifestPromise) return _customManifestPromise;
    _customManifestPromise = (async () => {
      const resp = await fetch('/creature-sprite-custom-manifest');
      if (!resp.ok) throw new Error(`manifest: HTTP ${resp.status}`);
      _customManifest = await resp.json();
      return _customManifest;
    })();
    try { return await _customManifestPromise; }
    finally { _customManifestPromise = null; }
  }

  // Pre-v2 cropAutogenSprite stored every sprite as a 96×96 PNG even
  // when the creature only filled a small middle region. Detect via PNG
  // IHDR (8-byte signature + 4-byte length + 4-byte 'IHDR' + width/
  // height u32s, big-endian) without a full decode.
  async function isLegacyPaddedPng(blob) {
    if (!blob || blob.size < 24) return false;
    const buf = new Uint8Array(await blob.slice(0, 24).arrayBuffer());
    if (buf[0] !== 0x89 || buf[1] !== 0x50) return false;
    const w = (buf[16] << 24) | (buf[17] << 16) | (buf[18] << 8) | buf[19];
    const h = (buf[20] << 24) | (buf[21] << 16) | (buf[22] << 8) | buf[23];
    return w === SPRITE_SIZE && h === SPRITE_SIZE;
  }

  async function retrimStoredBlob(blob) {
    const bmp = await createImageBitmap(blob);
    try {
      const { blob: trimmed } = await scanAndCrop(bmp, 0, 0, bmp.width, bmp.height);
      return trimmed;
    } finally {
      if (bmp.close) bmp.close();
    }
  }

  async function getAllIconKeys() {
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_ICONS, 'readonly');
      const req = tx.objectStore(STORE_ICONS).getAllKeys();
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }

  // Source-of-truth scan. Returns what actually lives in IDB right now
  // across the requested range, so a refresh / localStorage clear / IDB
  // wipe all surface accurately. Counts only autogen keys (the bulk
  // download's primary unit of progress); custom progress is reported
  // separately via customSpeciesDone / customSpeciesTotal.
  async function getDownloadStatus(opts = {}) {
    const sheetFrom = opts.sheetFrom || 1;
    const sheetTo = opts.sheetTo || 150;
    const indexFrom = opts.indexFrom || 1;
    const indexTo = opts.indexTo || 150;
    const keys = await getAllIconKeys();
    const have = new Set(keys);
    const sheetsComplete = new Set();
    const neededPerSheet = indexTo - indexFrom + 1;
    let iconsPresent = 0;
    for (let b = sheetFrom; b <= sheetTo; b++) {
      let count = 0;
      for (let a = indexFrom; a <= indexTo; a++) {
        if (have.has(`${a}-${b}`)) count++;
      }
      iconsPresent += count;
      if (count === neededPerSheet) sheetsComplete.add(b);
    }
    const customDone = getCustomDoneSpecies();
    return {
      sheetsComplete,
      sheetsTotal: sheetTo - sheetFrom + 1,
      iconsPresent,
      iconsTotal: (sheetTo - sheetFrom + 1) * neededPerSheet,
      customSpeciesDone: customDone.size,
      customSpeciesTotal: SPECIES_MAX,
    };
  }

  // opts:
  //   sheetFrom / sheetTo: partner-B sheet range (1..150 by default)
  //   indexFrom / indexTo: partner-A crop range (1..150)
  //   signal: AbortSignal — caller can cancel
  //   onProgress({ sheetsDone, sheetsTotal, currentSheet, indexInSheet, phase, customSpeciesDone, customSpeciesTotal })
  async function bulkDownload(opts = {}) {
    const sheetFrom = opts.sheetFrom || 1;
    const sheetTo = opts.sheetTo || 150;
    const indexFrom = opts.indexFrom || 1;
    const indexTo = opts.indexTo || 150;
    const signal = opts.signal;
    const onProgress = opts.onProgress || (() => {});

    if (global.Species && typeof global.Species.ensureLoaded === 'function') {
      try { await global.Species.ensureLoaded(); } catch {}
    }

    const keys = await getAllIconKeys();

    // Migrate any legacy 96×96 padded PNGs to tight-bbox crops in place.
    // Purely local — no network — so users who already downloaded the
    // whole set don't pay to fix them. Skip after the first successful
    // pass via a flag.
    const REPAIR_DONE_KEY = 'cc.spritesRepairDone';
    if (localStorage.getItem(REPAIR_DONE_KEY) !== '1') {
      for (let i = 0; i < keys.length; i++) {
        if (signal && signal.aborted) return { cancelled: true };
        const key = keys[i];
        // Custom keys (`a-b:cN`) are written tight from the start;
        // skip them so the migration doesn't no-op-scan thousands of
        // already-correct entries.
        if (typeof key === 'string' && key.includes(':c')) continue;
        if (i % 50 === 0) {
          onProgress({
            sheetsDone: 0, sheetsTotal: sheetTo - sheetFrom + 1,
            currentSheet: 0, indexInSheet: i, phase: 'repairing',
          });
        }
        const blob = await idbGet(key);
        if (!(await isLegacyPaddedPng(blob))) continue;
        const trimmed = await retrimStoredBlob(blob);
        if (trimmed) await idbPut(key, trimmed);
      }
      localStorage.setItem(REPAIR_DONE_KEY, '1');
    }

    // --- PASS 1: autogen sheets (resume-aware via per-cell IDB scan).
    const have = new Set(keys);
    const neededPerSheet = indexTo - indexFrom + 1;
    const sheetComplete = new Set();
    for (let b = sheetFrom; b <= sheetTo; b++) {
      let count = 0;
      for (let a = indexFrom; a <= indexTo; a++) {
        if (have.has(autogenKey(a, b))) count++;
      }
      if (count === neededPerSheet) sheetComplete.add(b);
    }
    localStorage.setItem(DOWNLOADED_KEY,
      JSON.stringify([...sheetComplete].sort((a, b) => a - b)));

    const totalSheets = sheetTo - sheetFrom + 1;
    let finished = sheetComplete.size;
    const customDone = getCustomDoneSpecies();
    const totalCustom = Math.min(SPECIES_MAX, sheetTo);

    for (let b = sheetFrom; b <= sheetTo; b++) {
      if (signal && signal.aborted) return { cancelled: true };
      if (sheetComplete.has(b)) continue;

      onProgress({
        sheetsDone: finished, sheetsTotal: totalSheets,
        currentSheet: b, indexInSheet: 0, phase: 'fetching',
        customSpeciesDone: customDone.size, customSpeciesTotal: totalCustom,
      });

      const bmp = await getSheetBitmap(b);

      for (let a = indexFrom; a <= indexTo; a++) {
        if (signal && signal.aborted) {
          if (bmp && bmp.close) bmp.close();
          _sheetCache.delete(`/creature-sprite/${b}`);
          return { cancelled: true };
        }
        const key = autogenKey(a, b);
        if (have.has(key)) continue;
        const blob = await cropAutogenSprite(bmp, a);
        await idbPut(key, blob);
        have.add(key);
        if (a % 20 === 0) {
          onProgress({
            sheetsDone: finished, sheetsTotal: totalSheets,
            currentSheet: b, indexInSheet: a, phase: 'cropping',
            customSpeciesDone: customDone.size, customSpeciesTotal: totalCustom,
          });
        }
      }

      _sheetCache.delete(`/creature-sprite/${b}`);
      if (bmp && bmp.close) bmp.close();

      markSheetDownloaded(b);
      finished++;
      onProgress({
        sheetsDone: finished, sheetsTotal: totalSheets,
        currentSheet: b, indexInSheet: indexTo, phase: 'done',
        customSpeciesDone: customDone.size, customSpeciesTotal: totalCustom,
      });
    }

    // --- PASS 2: custom (hand-drawn) sheets, alpha-scanned per cell.
    // For each species B in 1..min(150, sheetTo), fetch its directory's
    // variant sheets in manifest order, alpha-scan each cell A in
    // 1..min(150, indexTo). The output is, per cell `(A, B)`, the list
    // of variant indices (positions in the manifest) whose cell is
    // non-blank. That list — written to the `variants` store — defines
    // how many forms exist for that fusion; a uniform draw at spawn
    // time picks one. Cells with no filled custom variants stay
    // autogen-only.
    let manifest = null;
    try { manifest = await getCustomManifest(); }
    catch {
      // Manifest unreachable (offline, no custom dir on server) → skip
      // pass 2 entirely, leaving every cell to fall back to autogen.
      onProgress({
        sheetsDone: finished, sheetsTotal: totalSheets,
        currentSheet: 0, indexInSheet: 0, phase: 'custom-skipped',
        customSpeciesDone: customDone.size, customSpeciesTotal: totalCustom,
      });
      return { cancelled: false };
    }

    for (let b = sheetFrom; b <= Math.min(sheetTo, SPECIES_MAX); b++) {
      if (signal && signal.aborted) return { cancelled: true };
      if (customDone.has(b)) continue;
      const variants = manifest[String(b)];
      if (!variants || variants.length === 0) {
        markCustomDone(b);
        continue;
      }

      // Per-cell variant slots so far. cellVariants[a] is the array of
      // manifest-indices whose cell `(a, b)` is non-blank, in manifest
      // order so spawn-time uniform draws are stable.
      const cellVariants = new Array(indexTo + 1);
      for (let a = indexFrom; a <= indexTo; a++) cellVariants[a] = [];

      for (let vi = 0; vi < variants.length; vi++) {
        if (signal && signal.aborted) return { cancelled: true };
        const variantSuffix = variants[vi];
        onProgress({
          sheetsDone: finished, sheetsTotal: totalSheets,
          currentSheet: b, indexInSheet: 0, phase: 'custom-fetching',
          customSpeciesDone: customDone.size, customSpeciesTotal: totalCustom,
          customVariant: variantSuffix, customVariantNum: vi + 1,
          customVariantTotal: variants.length,
        });

        let bmp;
        try { bmp = await getCustomSheetBitmap(b, variantSuffix); }
        catch { continue; }  // missing variant: skip silently

        for (let a = indexFrom; a <= Math.min(indexTo, SPECIES_MAX); a++) {
          if (signal && signal.aborted) {
            if (bmp && bmp.close) bmp.close();
            return { cancelled: true };
          }
          const blob = await cropCustomSpriteIfFilled(bmp, a);
          if (!blob) continue;  // blank cell — don't store; not a variant
          const slot = cellVariants[a].length;
          cellVariants[a].push(vi);
          await idbPut(customKey(a, b, slot), blob);
        }

        const url = variantSuffix
          ? `/creature-sprite-custom/${b}/${variantSuffix}`
          : `/creature-sprite-custom/${b}`;
        _sheetCache.delete(url);
        if (bmp && bmp.close) bmp.close();
      }

      // Persist the per-cell variant table for this B.
      for (let a = indexFrom; a <= Math.min(indexTo, SPECIES_MAX); a++) {
        const list = cellVariants[a];
        const cellKey = `${a}-${b}`;
        if (list.length > 0) {
          await varPut(cellKey, list);
          _bumpVariantCacheEntry(cellKey, list.length);
        }
      }
      markCustomDone(b);
      customDone.add(b);
      onProgress({
        sheetsDone: finished, sheetsTotal: totalSheets,
        currentSheet: b, indexInSheet: indexTo, phase: 'custom-done',
        customSpeciesDone: customDone.size, customSpeciesTotal: totalCustom,
      });
    }

    // Pass 2 fully done — write the compact 22.5KB summary blob so
    // future loads can skip the per-cell IDB walk entirely (one
    // get vs. ~17 600 entries was 67 seconds on iOS).
    try { await _writeVariantSummary(); }
    catch (e) { _logSpriteError('bulkDownload/writeVariantSummary', e); }

    return { cancelled: false };
  }

  async function deleteAllSprites() {
    localStorage.removeItem(DOWNLOADED_KEY);
    localStorage.removeItem(CUSTOM_DONE_KEY);
    _variantCountCache = null;
    _variantSummaryLoaded = false;
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction([STORE_ICONS, STORE_VARIANTS], 'readwrite');
      tx.objectStore(STORE_ICONS).clear();
      tx.objectStore(STORE_VARIANTS).clear();
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }

  global.Sprites = {
    getSpriteUrl, getSpriteBlob, getSpriteBlobsBatch,
    getDefaultSpriteUrl, getDefaultSpriteBlob,
    getCellVariantCount, getCellVariantCountsBatch,
    bulkDownload, getDownloadedSheets, getDownloadStatus, deleteAllSprites,
    getCustomManifest,
    getInflightCount,
    rebuildVariantSummary: _writeVariantSummary,
  };
})(typeof window !== 'undefined' ? window : globalThis);
